section.programlisting:
void foo() {
  Coordination c = coordinator.create("work", 0);
  try {
    doWork(c);
  }
  catch (Exception e) {
    c.fail(e);
  }
  finally {
    c.end();
  }
}

void foo() {
  Coordination c = coordinator.begin("work", 0);
  try {
    doWork();
  } catch (Exception e) {
    c.fail(e);
  } finally {
    c.end();
  }
}

void doWork() {
  if (coordinator.addParticipant(this)) {
    beginWork();
  } else {
    beginWork();
    finishWork();
  }
}

void ended(Coordination c) {
  finishWork();
}

void failed(Coordination c) {
  undoWork();
}
